test.describe('Usability Coverage', () => {
  test('TFUS-001: keeps navigation and guidance visible for a first-time user', async ({ page }) => {
    await page.goto('/');
    await page.waitForLoadState('domcontentloaded');

    await expect(page.getByRole('heading').first()).toBeVisible();
  });
});

test.describe('Responsive Coverage', () => {
  test('TFRM-001: keeps the core journey visible across common viewport sizes', async ({ page }) => {
    const viewports = [
      { name: 'mobile', width: 390, height: 844 },
      { name: 'tablet', width: 768, height: 1024 },
      { name: 'desktop', width: 1440, height: 900 },
    ];

    for (const viewport of viewports) {
      await page.setViewportSize({ width: viewport.width, height: viewport.height });
      await page.goto('/');
      await page.waitForLoadState('domcontentloaded');
      await expect(page.locator('body')).toBeVisible();
      await expect(page.getByRole('heading').first()).toBeVisible();
      await expect(page.getByText('A/B Testing', { exact: true }).first(), 'A/B Testing should stay visible at ' + viewport.name + ' viewport').toBeVisible();
      await expect(page.getByText('Add/Remove Elements', { exact: true }).first(), 'Add/Remove Elements should stay visible at ' + viewport.name + ' viewport').toBeVisible();
      await expect(page.getByText('Basic Auth', { exact: true }).first(), 'Basic Auth should stay visible at ' + viewport.name + ' viewport').toBeVisible();
      await expect(page.getByText('Broken Images', { exact: true }).first(), 'Broken Images should stay visible at ' + viewport.name + ' viewport').toBeVisible();
      await expect(page.getByText('Canvas', { exact: true }).first(), 'Canvas should stay visible at ' + viewport.name + ' viewport').toBeVisible();
    }
  });

  test('TFRM-002: responds to a touch tap at mobile viewport', async ({ page }) => {
    await page.setViewportSize({ width: 390, height: 844 });
    await page.goto('/');
    await page.waitForLoadState('domcontentloaded');

    // Static introspection can't see touch-specific JS handlers, so this is
    // a smoke check that A/B Testing accepts a tap without erroring - not a
    // claim about what it does in response.
    const locator = page.getByText('A/B Testing', { exact: true }).first();
    await locator.scrollIntoViewIfNeeded();
    await locator.dispatchEvent('touchstart');
    await locator.dispatchEvent('touchend');
    await expect(page.locator('body')).toBeVisible();
  });
});

